// landlord, address, and figure is invented — no real portfolio data.
// Time-sensitive dates (tokens like @@ISO+24@@) are resolved relative to
// today at load time, so the dashboard's critical-date tiles stay live.
const _d = n => { const t = new Date(); t.setDate(t.getDate() + n); return t; };
const _pad = x => String(x).padStart(2, "0");
const _iso = n => { const t = _d(n); return `${t.getFullYear()}-${_pad(t.getMonth() + 1)}-${_pad(t.getDate())}`; };
const _mdy = n => { const t = _d(n); return `${t.getMonth() + 1}/${t.getDate()}/${t.getFullYear()}`; };
const _pretty = n => _d(n).toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" });
